const body = $input.first().json.body || {};
const entry = (body.entry && body.entry[0]) || {};
const messaging = (entry.messaging && entry.messaging[0]) || null;

if (!messaging || !messaging.message || !messaging.message.text) {
  return [{ json: { hasMessage: false } }];
}

return [{
  json: {
    hasMessage: true,
    from: messaging.sender.id,
    igAccountId: messaging.recipient.id,
    text: messaging.message.text,
    messageId: messaging.message.mid,
    timestamp: messaging.timestamp
  }
}];

const raw = $input.first().json.content[0].text;
let cleaned = raw.trim();
if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
}

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    nivel: 'consulta',
    interes: '',
    reply: 'Gracias por tu mensaje, en breve te contactamos con mas informacion.',
    resumen: null
  };
}

const prev = $('Extract Message').first().json;
const now = new Date().toISOString();

const urgenciaPorNivel = { consulta: 'baja', interesado: 'media', lead_caliente: 'alta' };

return [{
  json: {
    fecha: now,
    canal: 'instagram',
    nombre: (parsed.resumen && parsed.resumen.nombre && parsed.resumen.nombre !== 'No informado') ? parsed.resumen.nombre : '',
    telefono: prev.from,
    mensaje: prev.text,
    clasificacion: parsed.nivel || 'consulta',
    interes: parsed.interes || '',
    urgencia: urgenciaPorNivel[parsed.nivel] || 'media',
    estado: 'nuevo',
    ultimo_contacto: now,
    follow_up_count: 0,
    suggested_reply: parsed.reply || '',
    resumen_lead: parsed.resumen ? JSON.stringify(parsed.resumen) : '',
    igAccountId: prev.igAccountId,
    message_id: prev.messageId
  }
}];

const d = $input.first().json;
return [{
  json: {
    to: d.telefono,
    text: d.suggested_reply,
    igAccountId: d.igAccountId
  }
}];

// TIP: reemplaza este numero por tu WhatsApp personal (con codigo de pais, sin +, ej '5215512345678')
// Este nodo notifica por WhatsApp aunque el lead haya llegado por Instagram, para que lo veas rapido,
// con el resumen estructurado que pide el playbook de ventas.
const OWNER_WHATSAPP_NUMBER = 'REPLACE_WITH_OWNER_NUMBER';
const OWNER_PHONE_NUMBER_ID = 'REPLACE_WITH_YOUR_WHATSAPP_PHONE_NUMBER_ID';

const lead = $('Parse Claude Response').first().json;

let r = {};
try { r = lead.resumen_lead ? JSON.parse(lead.resumen_lead) : {}; } catch (e) { r = {}; }

const nd = (v) => (v && String(v).trim()) ? v : 'No informado';

const text = [
  '🔥 LEAD CALIENTE (Instagram)',
  'Nombre: ' + nd(r.nombre),
  'Qué busca: ' + nd(r.que_busca),
  'Modelo: ' + nd(r.modelo),
  'Presupuesto: ' + nd(r.presupuesto),
  'Motivo de compra: ' + nd(r.motivo_compra),
  'Forma de pago: ' + nd(r.forma_pago),
  'Nivel de intención: ' + nd(r.nivel_intencion),
  'Duda/objeción: ' + nd(r.duda_objecion),
  'Información importante: ' + nd(r.informacion_importante),
  'Último mensaje del cliente: ' + nd(lead.mensaje),
  'Siguiente acción recomendada: ' + nd(r.siguiente_accion),
  'Usuario de Instagram: ' + lead.telefono
].join('\n');

return [{
  json: {
    to: OWNER_WHATSAPP_NUMBER,
    text,
    phoneNumberId: OWNER_PHONE_NUMBER_ID
  }
}];
